package im.platform.client.ui.i18n
import androidx.compose.runtime.*
val LocalLanguage=staticCompositionLocalOf { "en" }
val locales=listOf("en","zh-CN","ja-JP")
val languageNames=listOf("English","简体中文","日本語")
const val languageEntry="Language / 语言 / 言語"
fun validLocale(value:String?)=value=="en"||value=="zh-CN"||value=="ja-JP"
val resources:Map<String,Map<String,String>> = mapOf("en" to en,"zh-CN" to zhCN,"ja-JP" to jaJP)
fun translate(locale:String?,key:String,params:Map<String,Any> = emptyMap(),data:Map<String,Map<String,String>> = resources):String {
 val language=if(validLocale(locale))locale else "en"
 check(data["en"]?.containsKey(key)==true){"Missing English language key: "+key}
 val template=data[language]?.get(key)?:data["en"]?.get(key)?:error("Missing English language key: "+key)
 return Regex("\\{([A-Za-z]+)\\}").replace(template){match->params[match.groupValues[1]]?.toString()?:match.value}
}
class TextLookup(private val locale:String){operator fun invoke(key:String,vararg params:Pair<String,Any>)=translate(locale,key,params.toMap())}
@Composable fun useText():TextLookup=TextLookup(LocalLanguage.current)
