fun displayText(locale:String,value:String):String {
 if(value.isEmpty())return ""
 if(value.startsWith("Sync "))return translate(locale,"error.sync",mapOf("reason" to translate(locale,errorKey(value.substring(5)))))
 return translate(locale,sourceDisplayKeys[value]?:errorKeys[value]?:if(resources["en"]!!.containsKey(value))value else "error.operation")
}
